        /* currency: one state for every option; placeholder rates as on the homepage */
        (function(){
          const R={usd:1,eur:.86,gbp:.75},S={usd:'$',eur:'€',gbp:'£'};
          const C={code:'usd',fmt(v){return S[C.code]+(v*R[C.code]).toFixed(2);},
            set(c){C.code=c;document.querySelectorAll('[data-p]').forEach(el=>el.textContent=C.fmt(+el.dataset.p));
              document.querySelectorAll('.cur').forEach(w=>{w.querySelector('button span').textContent=c.toUpperCase();w.querySelectorAll('li').forEach(li=>li.classList.toggle('on',li.dataset.c===c));});}};
          document.addEventListener('click',e=>{
            const li=e.target.closest('.cur li');if(li){C.set(li.dataset.c);li.closest('.cur').classList.remove('open');return;}
            const b=e.target.closest('.cur button');document.querySelectorAll('.cur.open').forEach(w=>{if(!b||w!==b.parentNode){w.classList.remove('open');w.querySelector('button').setAttribute('aria-expanded','false');}});
            if(b){const w=b.parentNode,o=w.classList.toggle('open');b.setAttribute('aria-expanded',o);}
          });
          RS.cur=C;
        })();
        
